def analyze(g):
    n=round((len(g)+1)/5)
    border=Counter(v for r in g for v in r).most_common(1)[0][0]
    key_shape=None; sqcolors=[]
    for bi in range(n):
        rows=g[bi*5:bi*5+4]
        for bj in range(n):
            sub=[r[bj*5:bj*5+4] for r in rows]
            cells={(x,y) for y in range(4) for x in range(4) if sub[y][x] and sub[y][x]!=border}
            for c in {sub[y][x] for x,y in cells}:
                cc={(x,y) for x,y in cells if sub[y][x]==c}
                if len(cc)==4 and any(all((x+dx,y+dy) in cc for dx in (0,1) for dy in (0,1)) for x in range(3) for y in range(3)):
                    sqcolors.append((bi,c))
                elif key_shape is None:
                    key_shape=cc
    return key_shape, dict(sqcolors)

